mapper.select:
/* SvcReqCommentMapper.findLatestComments */
SELECT SVC_REQ_CMT_SN   AS svcReqCmtSn,
       SVC_REQ_CMT_TTL  AS svcReqCmtTtl,
       SVC_REQ_CMT_CN   AS svcReqCmtCn,
       SVC_REQ_CMT_REG_DT AS svcReqCmtRegDt
  FROM SVC_REQ_COMMENT
 WHERE SVC_REQ_SN = #{svcReqSn}
 ORDER BY SVC_REQ_CMT_SN DESC
 LIMIT #{limit}
